CREATE FUNCTION public.hub_project_number() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prefix text; seq integer; BEGIN PERFORM 1 FROM public.clients WHERE id=NEW.client_id FOR UPDATE; SELECT code||'-'||extract(year from NEW.opened_on)::integer||'-' INTO prefix FROM public.clients WHERE id=NEW.client_id; SELECT coalesce(max(substring(code from length(prefix)+1)::integer),0)+1 INTO seq FROM public.projects WHERE client_id=NEW.client_id AND code LIKE prefix||'%' AND substring(code from length(prefix)+1) ~ '^[0-9]+$'; NEW.code:=prefix||lpad(seq::text,greatest(2,length(seq::text)),'0'); NEW.created_by:=auth.uid(); RETURN NEW; END $$; CREATE TRIGGER project_number BEFORE INSERT ON public.projects FOR EACH ROW EXECUTE FUNCTION public.hub_project_number();
CREATE FUNCTION public.hub_project_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.project_members(project_id,user_id,role) VALUES(NEW.id,NEW.created_by,'lead'); RETURN NEW; END $$; CREATE TRIGGER project_lead AFTER INSERT ON public.projects FOR EACH ROW EXECUTE FUNCTION public.hub_project_lead(); CREATE TRIGGER projects_touch BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE FUNCTION public.hub_member_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN pid:=CASE WHEN TG_OP='DELETE' THEN OLD.project_id ELSE NEW.project_id END; PERFORM 1 FROM public.projects WHERE id=pid FOR UPDATE; IF TG_OP='UPDATE' AND (NEW.project_id<>OLD.project_id OR NEW.user_id<>OLD.user_id) THEN RAISE EXCEPTION 'Membership identity cannot change'; END IF; IF TG_OP<>'DELETE' THEN IF NEW.role='client_viewer' AND public.is_investigator(NEW.user_id) THEN RAISE EXCEPTION 'Client viewers must not have a FridayAnalytics role'; ELSIF NEW.role<>'client_viewer' AND NOT public.is_investigator(NEW.user_id) THEN RAISE EXCEPTION 'Lead, analyst and reviewer roles require an investigator'; END IF; END IF; IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND OLD.role='lead' AND NEW.role<>'lead') THEN IF OLD.role='lead' AND NOT EXISTS(SELECT 1 FROM public.project_members WHERE project_id=pid AND role='lead' AND user_id<>OLD.user_id) THEN RAISE EXCEPTION 'Keep at least one lead. Add another lead first.'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$; CREATE TRIGGER member_guard BEFORE INSERT OR UPDATE OR DELETE ON public.project_members FOR EACH ROW EXECUTE FUNCTION public.hub_member_guard();
CREATE FUNCTION public.hub_brief_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.projects WHERE id=NEW.project_id FOR UPDATE; SELECT coalesce(max(version),0)+1 INTO NEW.version FROM public.project_briefs WHERE project_id=NEW.project_id; NEW.authored_by:=auth.uid(); SELECT display_name INTO NEW.authored_by_name FROM public.profiles WHERE id=auth.uid(); NEW.authored_at:=clock_timestamp(); RETURN NEW; END $$; CREATE TRIGGER brief_version BEFORE INSERT ON public.project_briefs FOR EACH ROW EXECUTE FUNCTION public.hub_brief_version();
CREATE FUNCTION public.hub_criteria_latest() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.projects WHERE id=NEW.project_id FOR UPDATE; IF NEW.brief_id IS DISTINCT FROM (SELECT id FROM public.project_briefs WHERE project_id=NEW.project_id ORDER BY version DESC LIMIT 1) THEN RAISE EXCEPTION 'Criteria belong to the latest brief only'; END IF; RETURN NEW; END $$; CREATE TRIGGER criteria_latest BEFORE INSERT ON public.project_criteria FOR EACH ROW EXECUTE FUNCTION public.hub_criteria_latest();
CREATE TRIGGER brief_immutable BEFORE UPDATE OR DELETE ON public.project_briefs FOR EACH ROW EXECUTE FUNCTION public.block_mutation(); CREATE TRIGGER criteria_immutable BEFORE UPDATE OR DELETE ON public.project_criteria FOR EACH ROW EXECUTE FUNCTION public.block_mutation(); CREATE TRIGGER assessment_immutable BEFORE UPDATE OR DELETE ON public.project_assessments FOR EACH ROW EXECUTE FUNCTION public.block_mutation(); CREATE TRIGGER event_immutable BEFORE UPDATE OR DELETE ON public.project_events FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE FUNCTION public.hub_assessment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.assessed_by:=auth.uid(); SELECT display_name INTO NEW.assessed_by_name FROM public.profiles WHERE id=auth.uid(); NEW.assessed_at:=clock_timestamp(); IF NOT EXISTS(SELECT 1 FROM public.project_criteria c JOIN public.project_briefs b ON b.id=c.brief_id WHERE c.id=NEW.criterion_id AND b.version=(SELECT max(version) FROM public.project_briefs WHERE project_id=NEW.project_id)) THEN RAISE EXCEPTION 'Assess against the current brief'; END IF; RETURN NEW; END $$; CREATE TRIGGER assessment_guard BEFORE INSERT ON public.project_assessments FOR EACH ROW EXECUTE FUNCTION public.hub_assessment_guard();
CREATE FUNCTION public.hub_output_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Outputs cannot be deleted'; END IF; IF TG_OP='INSERT' THEN IF NEW.status NOT IN ('draft','in_review') OR NEW.shared_with_client THEN RAISE EXCEPTION 'Outputs start as draft or in review, unshared'; END IF; NEW.created_by:=auth.uid(); SELECT display_name INTO NEW.created_by_name FROM public.profiles WHERE id=auth.uid(); NEW.approved_by:=NULL; NEW.approved_at:=NULL; NEW.delivered_at:=NULL; ELSE IF NEW.project_id<>OLD.project_id OR NEW.created_by<>OLD.created_by OR NEW.id<>OLD.id THEN RAISE EXCEPTION 'Output identity is immutable'; END IF; IF OLD.status='withdrawn' THEN RAISE EXCEPTION 'Withdrawn is final'; END IF; IF OLD.status IN ('approved','delivered') AND (NEW.brief_id,NEW.params,NEW.file_name,NEW.size_bytes,NEW.sha256,NEW.location,NEW.title,NEW.kind,NEW.item_count) IS DISTINCT FROM (OLD.brief_id,OLD.params,OLD.file_name,OLD.size_bytes,OLD.sha256,OLD.location,OLD.title,OLD.kind,OLD.item_count) THEN RAISE EXCEPTION 'Approved output content is immutable'; END IF; IF NEW.status<>OLD.status AND NOT ((OLD.status='draft' AND NEW.status='in_review') OR (OLD.status='in_review' AND NEW.status IN ('draft','approved')) OR (OLD.status='approved' AND NEW.status='delivered') OR NEW.status='withdrawn') THEN RAISE EXCEPTION 'Move outputs one step at a time'; END IF; IF (NEW.status IN ('approved','delivered','withdrawn') AND NEW.status<>OLD.status) OR NEW.shared_with_client IS DISTINCT FROM OLD.shared_with_client THEN IF NOT public.can_manage_project(auth.uid(),NEW.project_id) THEN RAISE EXCEPTION 'Only a lead or owner can approve, deliver, withdraw or share'; END IF; END IF; NEW.approved_by:=OLD.approved_by; NEW.approved_at:=OLD.approved_at; NEW.delivered_at:=OLD.delivered_at; END IF; IF NEW.status='approved' AND NEW.kind IN ('evidence_bundle','dataset') AND NEW.sha256 IS NULL THEN RAISE EXCEPTION 'A verified file hash is required before approval'; END IF; IF TG_OP='UPDATE' AND NEW.status='approved' AND OLD.status<>'approved' THEN NEW.approved_by:=auth.uid(); NEW.approved_at:=now(); END IF; IF TG_OP='UPDATE' AND NEW.status='delivered' AND OLD.status<>'delivered' THEN NEW.delivered_at:=now(); END IF; IF NEW.status='withdrawn' THEN NEW.shared_with_client:=false; END IF; IF NEW.shared_with_client AND NEW.status<>'delivered' THEN RAISE EXCEPTION 'Only delivered outputs can be shared'; END IF; IF NEW.location IS NOT NULL AND NEW.location NOT LIKE 'device:%' AND NEW.location NOT LIKE 'projects/%' THEN RAISE EXCEPTION 'Invalid output location'; END IF; RETURN NEW; END $$; CREATE TRIGGER output_guard BEFORE INSERT OR UPDATE OR DELETE ON public.project_outputs FOR EACH ROW EXECUTE FUNCTION public.hub_output_guard();
CREATE FUNCTION public.hub_event_log() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rowdata jsonb; pid uuid; ev text; who text; BEGIN rowdata:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; pid:=(rowdata->>'project_id')::uuid; IF TG_TABLE_NAME='projects' THEN pid:=(rowdata->>'id')::uuid; ev:=CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END; ELSIF TG_TABLE_NAME='project_members' THEN ev:=CASE WHEN TG_OP='DELETE' THEN 'member_removed' ELSE 'member_added' END; ELSIF TG_TABLE_NAME='project_briefs' THEN ev:='brief_versioned'; ELSIF TG_TABLE_NAME='project_cases' THEN ev:=CASE WHEN TG_OP='DELETE' THEN 'case_unlinked' ELSE 'case_linked' END; ELSIF TG_TABLE_NAME='project_items' THEN ev:=CASE WHEN TG_OP='DELETE' THEN 'item_unlinked' ELSE 'item_linked' END; ELSIF TG_TABLE_NAME='project_assessments' THEN ev:='assessed'; ELSIF TG_TABLE_NAME='project_outputs' THEN IF TG_OP='INSERT' THEN ev:='output_created'; ELSIF NEW.shared_with_client IS DISTINCT FROM OLD.shared_with_client THEN ev:=CASE WHEN NEW.shared_with_client THEN 'output_shared' ELSE 'output_unshared' END; ELSE ev:='output_status'; END IF; END IF; SELECT display_name INTO who FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.project_events(project_id,event,actor_id,actor_name,details) VALUES(pid,ev,auth.uid(),who,rowdata); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER project_event AFTER INSERT OR UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER member_event AFTER INSERT OR UPDATE OR DELETE ON public.project_members FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER brief_event AFTER INSERT ON public.project_briefs FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER case_event AFTER INSERT OR DELETE ON public.project_cases FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER item_event AFTER INSERT OR DELETE ON public.project_items FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER assessment_event AFTER INSERT ON public.project_assessments FOR EACH ROW EXECUTE FUNCTION public.hub_event_log(); CREATE TRIGGER output_event AFTER INSERT OR UPDATE ON public.project_outputs FOR EACH ROW EXECUTE FUNCTION public.hub_event_log();
CREATE FUNCTION public.hub_ref_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; BEGIN IF NEW.incident_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.incidents WHERE id=NEW.incident_id AND case_id=NEW.case_id) THEN RAISE EXCEPTION 'Incident must belong to the linked case'; END IF; IF NOT EXISTS(SELECT 1 FROM public.sources WHERE id=NEW.source_id AND kind='home_vault') THEN RAISE EXCEPTION 'Only home-vault records can be linked'; END IF; FOR f IN SELECT * FROM jsonb_array_elements(NEW.files) LOOP IF coalesce(f->>'file_id','')='' OR coalesce(f->>'filename','')='' OR coalesce(f->>'sha256','') !~ '^[a-fA-F0-9]{64}$' THEN RAISE EXCEPTION 'Every linked file requires an ID, filename and SHA-256 baseline'; END IF; END LOOP; NEW.linked_by:=auth.uid(); SELECT display_name INTO NEW.linked_by_name FROM public.profiles WHERE id=auth.uid(); NEW.linked_at:=clock_timestamp(); RETURN NEW; END $$; CREATE TRIGGER ref_guard BEFORE INSERT ON public.evidence_refs FOR EACH ROW EXECUTE FUNCTION public.hub_ref_guard();
CREATE FUNCTION public.hub_ref_linked() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.custody_events(source_id,evidence_ref_id,action,handler,notes) VALUES(NEW.source_id,NEW.id,'linked',NEW.linked_by_name,'Home-vault reference linked; hashes retained at linking'); RETURN NEW; END $$; CREATE TRIGGER ref_linked AFTER INSERT ON public.evidence_refs FOR EACH ROW EXECUTE FUNCTION public.hub_ref_linked();
CREATE FUNCTION public.hub_custody_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.source_id<>'cloud' AND NOT EXISTS(SELECT 1 FROM public.evidence_refs WHERE id=NEW.evidence_ref_id AND source_id=NEW.source_id AND public.is_investigator(auth.uid()) AND public.can_access_case(auth.uid(),case_id)) THEN RAISE EXCEPTION 'Case access required for home-vault custody'; END IF; RETURN NEW; END $$; CREATE TRIGGER home_custody_guard BEFORE INSERT ON public.custody_events FOR EACH ROW EXECUTE FUNCTION public.hub_custody_guard();
CREATE FUNCTION public.save_project_brief(p_project_id uuid,p_brief jsonb,p_criteria jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; c jsonb; BEGIN IF NOT public.can_manage_project(auth.uid(),p_project_id) THEN RAISE EXCEPTION 'Lead or owner required'; END IF; PERFORM 1 FROM public.projects WHERE id=p_project_id FOR UPDATE; INSERT INTO public.project_briefs(project_id,question,background,scope,out_of_scope,period_from,period_to,platforms,audience,output_kinds,constraints,change_note,authored_by) VALUES(p_project_id,p_brief->>'question',p_brief->>'background',p_brief->>'scope',p_brief->>'out_of_scope',nullif(p_brief->>'period_from','')::date,nullif(p_brief->>'period_to','')::date,ARRAY(SELECT jsonb_array_elements_text(coalesce(p_brief->'platforms','[]'))),p_brief->>'audience',ARRAY(SELECT jsonb_array_elements_text(coalesce(p_brief->'output_kinds','[]'))),p_brief->>'constraints',p_brief->>'change_note',auth.uid()) RETURNING id INTO bid; FOR c IN SELECT * FROM jsonb_array_elements(p_criteria) LOOP INSERT INTO public.project_criteria(brief_id,project_id,position,kind,label,description,required,weight) VALUES(bid,p_project_id,coalesce((c->>'position')::integer,0),c->>'kind',c->>'label',c->>'description',coalesce((c->>'required')::boolean,false),coalesce((c->>'weight')::numeric,1)); END LOOP; RETURN bid; END $$; REVOKE ALL ON FUNCTION public.save_project_brief(uuid,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_project_brief(uuid,jsonb,jsonb) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.hub_project_number(),public.hub_project_lead(),public.hub_member_guard(),public.hub_brief_version(),public.hub_criteria_latest(),public.hub_assessment_guard(),public.hub_output_guard(),public.hub_event_log(),public.hub_ref_guard(),public.hub_ref_linked(),public.hub_custody_guard() FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.clients IS 'Client portal is intentionally not built; portal_enabled remains false.';